// PhoneVault live-view auth gate (v5.0; v4.4 design + v5.0 mode-aware routing).
// Zero-dependency Node reverse proxy. Listens on 127.0.0.1:8080 ONLY.
// The per-run token (env PV_TOKEN, 256-bit, generated by the workflow step)
// is the only credential. Auth paths, in order:
//   (i)  request path starts with /<TOKEN>/  -> strip prefix, pass, and set
//        an HttpOnly cookie so the client's absolute-path subresources and
//        WebSocket connects (which cannot carry the prefix) still pass.
//   (ii) Cookie: pv=<TOKEN>                  -> pass.
//   (iii) anything else                      -> 404, empty body, no hints.
// Routing after the token strip depends on env PV_GATE_MODE, which the
// workflow sets to the mode that actually won the window:
//   slideshow (fallback.py is the ONLY server; ws-scrcpy never came up):
//        EVERY path -> 127.0.0.1:8001, with a /fallback prefix stripped when
//        present. v4.4-v4.9 routed non-/fallback paths to the (dead) video
//        port 8000, so the slideshow page loaded but its /frame.png image
//        and /tap /key /text controls all died with 502 - the page rendered,
//        the picture never did (owner screenshot, run #44). WebSocket
//        upgrades are refused outright: slideshow has no WS backend.
//   video (default; ws-scrcpy on 8000, fallback on 8001):
//        /fallback/... -> 127.0.0.1:8001 (prefix stripped), everything else
//        -> 127.0.0.1:8000 - exactly the v4.4 behaviour.
// The token is NEVER logged; only method + status + timestamp are logged.
'use strict';
const http = require('http');
const net = require('net');
const crypto = require('crypto');

const TOKEN = process.env.PV_TOKEN || '';
const PORT = 8080;
const HOST = '127.0.0.1';
const MODE = (process.env.PV_GATE_MODE || 'video').toLowerCase();
if (TOKEN.length < 32) {
  console.error('gate: PV_TOKEN missing or too short - refusing to start');
  process.exit(1);
}
const tokenBuf = Buffer.from(TOKEN);

function tokenEq(s) {
  if (typeof s !== 'string') return false;
  const b = Buffer.from(s);
  if (b.length !== tokenBuf.length) return false;
  return crypto.timingSafeEqual(b, tokenBuf);
}

function cookieToken(req) {
  const c = req.headers.cookie || '';
  for (const part of c.split(';')) {
    const kv = part.trim().split('=');
    if (kv[0] === 'pv' && kv.length >= 2) return kv.slice(1).join('=');
  }
  return '';
}

// Returns {ok, strippedPath, viaPrefix} for a raw request URL.
function authorize(rawUrl, req) {
  const url = rawUrl || '/';
  if (url.startsWith('/' + TOKEN + '/')) {
    return { ok: true, path: url.slice(TOKEN.length + 1), viaPrefix: true };
  }
  if (url === '/' + TOKEN) {
    return { ok: true, path: '/', viaPrefix: true };
  }
  if (tokenEq(cookieToken(req))) {
    return { ok: true, path: url, viaPrefix: false };
  }
  return { ok: false, path: '/', viaPrefix: false };
}

function stripFallback(path) {
  if (path === '/fallback') return '/';
  if (path.startsWith('/fallback/')) return path.slice('/fallback'.length);
  return path;
}

function route(path) {
  if (MODE === 'slideshow') {
    return { port: 8001, path: stripFallback(path) };
  }
  if (path === '/fallback' || path.startsWith('/fallback/')) {
    return { port: 8001, path: path.slice('/fallback'.length) || '/' };
  }
  return { port: 8000, path };
}

function deny(res) {
  res.writeHead(404, { 'Content-Length': '0' });
  res.end();
}

const server = http.createServer((req, res) => {
  const a = authorize(req.url, req);
  if (!a.ok) { deny(res); console.log(Date.now(), req.method, 404); return; }
  const r = route(a.path);
  const headers = Object.assign({}, req.headers, { host: '127.0.0.1:' + r.port });
  const up = http.request(
    { host: '127.0.0.1', port: r.port, method: req.method, path: r.path, headers },
    (ures) => {
      const uh = Object.assign({}, ures.headers);
      if (a.viaPrefix) {
        uh['set-cookie'] = 'pv=' + TOKEN + '; HttpOnly; Secure; SameSite=Strict; Path=/';
        const loc = uh.location;
        if (typeof loc === 'string' && loc.startsWith('/') && !loc.startsWith('/' + TOKEN + '/')) {
          uh.location = '/' + TOKEN + loc;
        }
      }
      res.writeHead(ures.statusCode || 502, uh);
      ures.pipe(res);
      console.log(Date.now(), req.method, ures.statusCode);
    }
  );
  up.on('error', () => {
    if (!res.headersSent) res.writeHead(502, { 'Content-Length': '0' });
    res.end();
    console.log(Date.now(), req.method, 502);
  });
  req.pipe(up);
});

server.on('upgrade', (req, socket, head) => {
  const a = authorize(req.url, req);
  if (!a.ok || MODE === 'slideshow') {
    // Slideshow has no WebSocket backend; refuse the upgrade outright
    // instead of proxying it at a port where nothing sane answers.
    socket.write('HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\n\r\n');
    socket.destroy();
    console.log(Date.now(), 'UPGRADE', 404);
    return;
  }
  const r = route(a.path);
  const up = net.connect(r.port, '127.0.0.1', () => {
    const lines = [req.method + ' ' + r.path + ' HTTP/' + req.httpVersion];
    for (let i = 0; i < req.rawHeaders.length; i += 2) {
      let k = req.rawHeaders[i];
      let v = req.rawHeaders[i + 1];
      if (k.toLowerCase() === 'host') v = '127.0.0.1:' + r.port;
      lines.push(k + ': ' + v);
    }
    up.write(lines.join('\r\n') + '\r\n\r\n');
    if (head && head.length) up.write(head);
    up.pipe(socket);
    socket.pipe(up);
    console.log(Date.now(), 'UPGRADE', 101);
  });
  up.on('error', () => socket.destroy());
  socket.on('error', () => up.destroy());
});

server.listen(PORT, HOST, () => {
  console.log('gate: listening on ' + HOST + ':' + PORT + ' (token length ' + TOKEN.length + ', mode ' + MODE + ')');
});
